/** General-record clinical notes only; psychotherapy notes are deliberately excluded. */
export async function listClinicalForPatient(patientId: string): Promise<NoteRow[]> {
  return query<NoteRow>(
    `SELECT id, 'clinical' AS kind, patient_id, practitioner_id, created_at, body
       FROM clinical_notes WHERE patient_id = ? ORDER BY created_at`,
    [patientId],
  );
}
